{
  "concepts": [
    {
      "conditions": [],
      "definition": "Draft 2020-12 schema urn:stdo:schema:product-definition:3 describes a layout-neutral overlay binding one STDO-defined product WHAT to identity, authority locations, bounded context, collective frame basis, realization, work carriers, bootstrap and composition.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 5,
          "quote": "\"description\": \"Layout-neutral exact STDO basis, identity, authority-location, bounded-context disambiguation, collective reference-frame basis, realization, work-carrier, bootstrap, and composition bindings for one STDO-defined product WHAT.\"",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/schemas/product-definition.schema.json#preamble",
          "start_line": 5
        }
      ],
      "key": "product_definition_schema",
      "label": "Product Definition Overlay schema"
    },
    {
      "conditions": [],
      "definition": "The schema's STDO binding distinguishes a Git source repository, mutable annotated-tag version-line discovery selector, and exact immutable installed release basis with deterministic manifest digest carrying tag, commit, tree and complete distribution identity.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 319,
          "quote": "\"description\": \"Mutable version-line discovery selector carried by an annotated Git tag. It is never operative constitutional authority without digest-bound explicit resolution and adoption.\"",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/schemas/product-definition.schema.json#preamble",
          "start_line": 319
        },
        {
          "end_line": 334,
          "quote": "\"description\": \"Digest of the deterministic installed-release manifest carrying tag, commit, tree, and complete distribution identity.\"",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/schemas/product-definition.schema.json#preamble",
          "start_line": 334
        }
      ],
      "key": "schema_stdo_binding",
      "label": "Exact STDO binding"
    },
    {
      "conditions": [],
      "definition": "Local disambiguation binds an exact lexical label, bounded-context identity, complete material candidate set, selected concept, resolution carrier, existing lawful authorities, semantic bases and exact governed scopes. A spelling is not a context-free concept identity.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 470,
          "quote": "\"description\": \"Exact lexical label being resolved; the label is not a context-free concept identity.\"",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/schemas/product-definition.schema.json#preamble",
          "start_line": 470
        },
        {
          "end_line": 478,
          "quote": "\"description\": \"Complete material candidate concept or clause references for the declared term, context, basis, and scope.\"",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/schemas/product-definition.schema.json#preamble",
          "start_line": 478
        }
      ],
