    {
      "conditions": [],
      "definition": "The JSON Product Definition template is an illustrative fill-in overlay: Replace Me product/context identities; source_project ./; product terms in specification/PRODUCT.md; an example Git repository; replacement channel, immutable release and digest; four basis-qualified standard entrypoints; bootstrap targets ./AGENTS.md and ./CLAUDE.md; empty additional authorities, axioms, overrides, common HOW and composition; illustrative disambiguation; one frame-basis reference; specification WHAT paths; one default build tenant; and Goals, tickets with backlog/active/completed lanes, comments and sprints carriers. These are template values, not an instantiated Product or accepted binding.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 7,
          "quote": "    \"definition_id\": \"urn:stdo:product-definition:replace-me\",\n    \"name\": \"Replace Me\",\n    \"source_project\": \"./\",",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/templates/PRODUCT_DEFINITION_TEMPLATE.json#preamble",
          "start_line": 5
        },
        {
          "end_line": 21,
          "quote": "        \"manifest_sha256\": \"REPLACE_WITH_64_LOWERCASE_HEX_SHA256\"",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/templates/PRODUCT_DEFINITION_TEMPLATE.json#preamble",
          "start_line": 21
