    },
    {
      "conditions": [],
      "definition": "An evaluation inventory distinguishes planning dispositions activate/non_material/residual, applicability premises true/false/unknown, and required-result evidence satisfied/missing/invalid. These are distinct domains rather than interchangeable coverage results.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 73,
          "quote": "- disposition: `activate | non_material | residual` (a planning choice, not\n  a coverage status; see Coverage And Residuals)\n- non-material evidence or residual and re-entry condition:\n- owning applicability predicate and true/false/unknown premises:\n- required-result identity and current satisfied/missing/invalid evidence:",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/templates/PROJECT_REFERENCE_FRAME_BASIS_TEMPLATE.md#Project%20Reference-Frame%20Basis%2FEvaluation%20Inventory",
          "start_line": 69
        }
      ],
      "key": "frame_evaluation_inventory",
      "label": "Evaluation inventory and result distinctions"
    },
    {
      "conditions": ["The Product adopts the Executive profile."],
      "definition": "Executive is the selected coordinating role that consumes closed results, preserves residuals, selects sufficient dependency-ready evaluations and chooses already-authorized actions. The role label supplies no Product meaning, implementation, mutation, acceptance or publication authority.",
      "exceptions": ["Another adopted configuration supplies its own coordination."],
      "grounding": [
        {
          "end_line": 146,
          "quote": "Executive selects the smallest dependency-ready activation set sufficient for\nthe next decision. It consumes closed results, preserves explicit residuals,\nand chooses only an already-authorized next action. It does not acquire Product\nmeaning, implementation, mutation, acceptance, or publication authority from\nthe Executive label.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/templates/PROJECT_REFERENCE_FRAME_BASIS_TEMPLATE.md#Project%20Reference-Frame%20Basis%2FExecutive%20Attention%2C%20Evaluation%2C%20And%20Action",
          "start_line": 142
        }
      ],
      "key": "frame_executive_role",
      "label": "Executive coordination role"
    },
    {
      "conditions": [],
      "definition": "Writer is a separately bound constructive activation carrying an exact work grant; direct entry and a role change from Executive remain subject to authority, admission, operation scope and closure conditions.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 173,
          "quote": "Executive performs no file or Git mutation. The same actor may construct only\nafter entering a separately bound Writer activation with the inherited exact\ngrant. Changing roles does not create authority or independent assessment.",
          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/templates/PROJECT_REFERENCE_FRAME_BASIS_TEMPLATE.md#Project%20Reference-Frame%20Basis%2FActivation%20And%20Return%20Topology",
          "start_line": 171
        }
      ],
      "key": "frame_writer_activation",
      "label": "Writer activation"
    },
    {
