          "section_id": "repo://stdo-v3-common/35fb4824a064a84df5af214a0d0e2da597c18ac6/source/standards/schemas/product-definition.schema.json#preamble",
          "start_line": 7
        },
        {
          "end_line": 243,
          "quote": "  \"additionalProperties\": false,",
